@startuml

class School {
  + Name : string
}

abstract class Person {
  + FirstName : string
  + LastName : string
}

class Teacher {
  + EmailAddress : string
}

class Student {
}

class ClassGroup {
  + Name : string
}

class Classroom {
  + Name : string
  + Capacity : int
}

class OtherRoom {
  + Name : string
  + SizeInSquareMeters : float
}

class TeachingAssignment {
  + Hours : int
}

Person <|-- Teacher
Person <|-- Student

School "1" -- "*" Teacher : employs
School "1" -- "*" Student : has
School "1" -- "0..1" Teacher : principal

Teacher "1..3" -- "*" School : teaches
Teacher "1" -- "*" TeachingAssignment : performs
School "1" -- "*" TeachingAssignment : has

Student "*" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
ClassGroup "10..31" -- "*" Student : contains

School "1" *-- "*" Classroom
School "1" *-- "*" OtherRoom

@enduml

